  // zanaat
  "onl.atl.zanaat": ["Zanaat", "Craft", "Oficio", "Ofício", "الحرفة", "Ремесло"],
  "onl.atl.zanaatSecilmedi": ["Zanaat seçilmedi", "No craft chosen", "Sin oficio elegido", "Nenhum ofício escolhido", "لم تُختر حرفة", "Ремесло не выбрано"],
  "onl.atl.zanaatAciklama": ["Atölye tek bir zanaatın tariflerini yapar. Tarifi olan her meslek seçilebilir; senin mesleğin olması gerekmez.", "The workshop makes the recipes of a single craft. Any trade that has recipes can be chosen; it need not be yours.", "El taller hace las recetas de un solo oficio. Se puede elegir cualquier oficio con recetas; no tiene que ser el tuyo.", "A oficina faz as receitas de um só ofício. Pode escolher-se qualquer ofício com receitas; não tem de ser o teu.", "تصنع الورشة وصفات حرفة واحدة. يمكن اختيار أي حرفة لها وصفات؛ ولا يلزم أن تكون حرفتك.", "Мастерская делает рецепты одного ремесла. Можно выбрать любое ремесло с рецептами; не обязательно своё."],
  "onl.atl.zanaatNot": ["Atölye seviyesi her yapıma +%1 kalite puanı katar.", "Each workshop level adds +%1 quality points to every make.", "Cada nivel del taller suma +%1 puntos de calidad a cada fabricación.", "Cada nível da oficina soma +%1 pontos de qualidade a cada fabrico.", "كل مستوى للورشة يضيف +%1 نقطة جودة إلى كل صنعة.", "Каждый уровень мастерской добавляет +%1 очков качества к каждому изделию."],
  "onl.atl.zanaatOneri": ["Önerilen: %1 (senin mesleğin). Seçince ücretsiz atanır.", "Suggested: %1 (your trade). Assigned free when chosen.", "Sugerido: %1 (tu oficio). Se asigna gratis al elegirlo.", "Sugerido: %1 (o teu ofício). Atribuído de graça ao escolher.", "المقترح: %1 (حرفتك). يُعيَّن مجانًا عند اختياره.", "Рекомендуется: %1 (твоё ремесло). Назначается бесплатно."],
  "onl.atl.zanaatSahibe": ["Zanaatı atölyenin sahibi seçer; seçilince üretim başlar.", "The workshop owner chooses the craft; production starts once it is chosen.", "El dueño del taller elige el oficio; la producción empieza al elegirlo.", "O dono da oficina escolhe o ofício; a produção começa depois de escolhido.", "صاحب الورشة يختار الحرفة؛ ويبدأ الإنتاج بعد اختيارها.", "Ремесло выбирает владелец мастерской; после выбора начинается производство."],
  "onl.atl.zanaatOnce": ["Önce atölyenin zanaatı seçilmeli.", "The workshop's craft must be chosen first.", "Primero hay que elegir el oficio del taller.", "Primeiro é preciso escolher o ofício da oficina.", "يجب أولًا اختيار حرفة الورشة.", "Сначала нужно выбрать ремесло мастерской."],
  "onl.atl.zanaatSec": ["Zanaatı seç", "Choose craft", "Elegir oficio", "Escolher ofício", "اختر الحرفة", "Выбрать ремесло"],
