  "onl.atl.zanaatIlk": ["İlk seçim ücretsizdir.", "The first choice is free.", "La primera elección es gratis.", "A primeira escolha é gratuita.", "الاختيار الأول مجاني.", "Первый выбор бесплатный."],
  "onl.atl.zanaatUcretsiz": ["%1 değişiklik daha ücretsiz.", "%1 more free change(s).", "%1 cambio(s) más gratis.", "Mais %1 mudança(s) gratuita(s).", "%1 تغيير(ات) مجانية إضافية.", "Ещё бесплатных смен: %1."],
  "onl.atl.zanaatBedel": ["Bu değişiklik %1 akçe tutar; bedel beyliğe gider.", "This change costs %1 akçe; the fee goes to the beylik.", "Este cambio cuesta %1 akçe; el importe va al beylicato.", "Esta mudança custa %1 akçe; o valor vai para o beylik.", "يكلّف هذا التغيير %1 أقجة؛ وتذهب الكلفة إلى الإمارة.", "Эта смена стоит %1 акче; плата уходит бейлику."],
